const text = String($json.chatInput || '').trim();
const words = text ? text.split(/\s+/).length : 0;
const reply = !text ? 'Say something!'
  : /^(hi|hello|merhaba|selam)\b/i.test(text) ? 'Merhaba! 👋 I am a Code node running on flow.'
  : `You wrote ${words} word(s). Reversed: "${[...text].reverse().join('')}"`;
return [{ json: { output: reply } }];
